import core.auth.UserAccountInfo;
import core.game.node.entity.player.info.*;
import core.game.system.communication.*;
import core.game.system.mysql.SQLTable;
import core.game.world.GameWorld;
import core.net.IoSession;
import core.storage.AccountStorageProvider;
import java.io.*;
import java.util.*;
import org.json.simple.JSONValue;
import org.json.simple.parser.JSONParser;

public final class PlayerOracle {
 interface Work {Object run() throws Exception;}
 static Map<String,Object> map(Object... entries){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<entries.length;i+=2)out.put((String)entries[i],entries[i+1]);return out;}
 static int number(Map<?,?> m,String key){return ((Number)m.get(key)).intValue();}
 static long longNumber(Map<?,?> m,String key){return ((Number)m.get(key)).longValue();}
 static String string(Map<?,?> m,String key){return (String)m.get(key);}
 static String error(Exception e){if(e instanceof NumberFormatException)return "number";if(e instanceof IndexOutOfBoundsException)return "index";if(e instanceof NullPointerException)return "null";if(e instanceof IllegalStateException)return "illegal_state";return "storage";}
 static Object attempt(Work work){try{return map("ok",work.run());}catch(Exception e){return map("error",error(e));}}
 static Integer rank(ClanRank rank){return rank==null?null:rank.ordinal();}
 static ClanRank rankValue(Object value){return value==null?null:ClanRank.values()[((Number)value).intValue()];}
 static ClanRank[] requirements(CommunicationInfo c){return new ClanRank[]{c.getJoinRequirement(),c.getMessageRequirement(),c.getKickRequirement(),c.getLootRequirement()};}
 static void requirement(CommunicationInfo c,int slot,ClanRank r){switch(slot){case 0:c.setJoinRequirement(r);break;case 1:c.setMessageRequirement(r);break;case 2:c.setKickRequirement(r);break;case 3:c.setLootRequirement(r);break;default:throw new IndexOutOfBoundsException();}}
 static Object contacts(Map<String,Contact> contacts){List<Object> out=new ArrayList<>();for(Map.Entry<String,Contact> e:contacts.entrySet()){Contact c=e.getValue();out.add(Arrays.asList(e.getKey(),c.getUsername(),c.getWorldId(),rank(c.getRank())));}return out;}
 static Object communication(CommunicationInfo c){List<Object> ranks=new ArrayList<>();for(ClanRank r:requirements(c))ranks.add(rank(r));return map("contacts",contacts(c.getContacts()),"blocked",new ArrayList<>(c.getBlocked()),"clanName",c.getClanName(),"currentClan",c.getCurrentClan(),"requirements",ranks,"lootShare",c.isLootShare(),"contactString",attempt(c::getContactString),"blockedString",c.getBlockedString(),"requirementString",attempt(c::getClanReqString));}
 static UserAccountInfo account(Map<?,?> input){UserAccountInfo a=UserAccountInfo.createDefault();a.setContacts(string(input,"contacts"));a.setBlocked(string(input,"blocked"));a.setClanName(string(input,"clanName"));a.setCurrentClan(string(input,"currentClan"));a.setClanReqs(string(input,"clanReqs"));return a;}
 static Object accountValues(UserAccountInfo info){List<Object> out=new ArrayList<>();for(Object value:info.toArray())out.add(value instanceof java.sql.Timestamp?((java.sql.Timestamp)value).getTime():value);return out;}
 static void set(UserAccountInfo a,int field,Object v){switch(field){case 0:a.setUsername((String)v);break;case 1:a.setPassword((String)v);break;case 2:a.setUid(((Number)v).intValue());break;case 3:a.setRights(((Number)v).intValue());break;case 4:a.setCredits(((Number)v).intValue());break;case 7:a.setMuteEndTime(((Number)v).longValue());break;case 8:a.setBanEndTime(((Number)v).longValue());break;case 9:a.setContacts((String)v);break;case 10:a.setBlocked((String)v);break;case 11:a.setClanName((String)v);break;case 12:a.setCurrentClan((String)v);break;case 13:a.setClanReqs((String)v);break;case 14:a.setTimePlayed(((Number)v).longValue());break;case 15:a.setLastLogin(((Number)v).longValue());break;default:throw new UnsupportedOperationException();}}
 static SQLTable table(Map<?,?> action){SQLTable table=new SQLTable();Map<?,?> values=(Map<?,?>)action.get("values");if(values!=null)for(String key:new String[]{"contacts","blocked","clanName","currentClan","clanReqs"}){String value=(String)values.get(key);if(value!=null&&value.isEmpty())value=Boolean.TRUE.equals(action.get("interned"))?"":new String("");table.values.put(key,value);}table.fail=(String)action.getOrDefault("fail",null);if(table.fail==null)table.fail="";return table;}
 static Object commActions(Map<?,?> input){CommunicationInfo c=new CommunicationInfo();List<Object> steps=new ArrayList<>();for(Object item:(List<?>)input.get("actions")){Map<?,?> a=(Map<?,?>)item;SQLTable table=table(a);Object result=attempt(()->{switch(string(a,"op")){case "account":c.parse(account(a));break;case "columns":c.parse(table);break;case "save_columns":c.save(table);break;case "put":Contact contact=new Contact(string(a,"username"));contact.setRank(rankValue(a.get("rank")));contact.setWorldId(number(a,"world"));c.getContacts().put(string(a,"key"),contact);break;case "rank":c.getContacts().get(string(a,"key")).setRank(rankValue(a.get("value")));break;case "block":c.getBlocked().add(string(a,"value"));break;case "requirement":requirement(c,number(a,"slot"),rankValue(a.get("value")));break;default:throw new UnsupportedOperationException();}return true;});steps.add(map("result",result,"state",communication(c),"trace",table.trace,"columns",table.values));}return steps;}
 static UIDInfo uid(Map<?,?> a){return new UIDInfo(string(a,"ip"),string(a,"computer"),string(a,"mac"),string(a,"serial"));}
 static Object uidState(UIDInfo uid){return map("ip",uid.getIp(),"computer",uid.getCompName(),"mac",uid.getMac(),"serial",uid.getSerial(),"string",uid.toString());}
 static Object uidActions(Map<?,?> input){UIDInfo[] current={new UIDInfo()};List<Object> steps=new ArrayList<>();for(Object item:(List<?>)input.get("actions")){Map<?,?> a=(Map<?,?>)item;Object result=attempt(()->{if(string(a,"op").equals("new"))current[0]=uid(a);else current[0].translate(Boolean.TRUE.equals(a.get("empty"))?new UIDInfo():uid(a));return true;});steps.add(map("result",result,"state",uidState(current[0])));}return steps;}
 static final class Storage implements AccountStorageProvider {
  List<Object> calls=new ArrayList<>();String fail="";
  public void update(UserAccountInfo info){calls.add(accountValues(info));if(fail.equals("illegal_state"))throw new IllegalStateException();if(!fail.isEmpty())throw new RuntimeException();}
  public boolean checkUsernameTaken(String s){throw new UnsupportedOperationException();}public UserAccountInfo getAccountInfo(String s){throw new UnsupportedOperationException();}public List<String> getUsernamesWithIP(String s){throw new UnsupportedOperationException();}public void store(UserAccountInfo a){throw new UnsupportedOperationException();}public void remove(UserAccountInfo a){throw new UnsupportedOperationException();}public List<String> getOnlineFriends(String s){throw new UnsupportedOperationException();}
 }
 static Object details(Map<?,?> input){oracle.Clock.value=longNumber(input,"now");oracle.Clock.reads=0;PlayerDetails d=PlayerDetails.getDetails("alice");Storage storage=new Storage();GameWorld.storage=storage;List<Object> steps=new ArrayList<>();for(Object item:(List<?>)input.get("actions")){Map<?,?> a=(Map<?,?>)item;Object result=attempt(()->{switch(string(a,"op")){case "set":int field=number(a,"field");Object v=a.get("value");switch(field){case 1:d.setPassword((String)v);break;case 3:set(d.accountInfo,field,v);break;case 4:d.setCredits(((Number)v).intValue());break;case 7:d.setMuteTime(((Number)v).longValue());break;case 8:d.setBanTime(((Number)v).longValue());break;case 14:d.setTimePlayed(((Number)v).longValue());break;case 15:d.setLastLogin(((Number)v).longValue());break;default:set(d.accountInfo,field,v);}break;case "flags":return map("banned",d.isBanned(),"muted",d.isMuted(),"permanent",d.isPermMute(),"rights",attempt(()->d.getRights().ordinal()));case "parsed":d.saveParsed=Boolean.TRUE.equals(a.get("value"));break;case "parse":d.getCommunication().parse(d.accountInfo);break;case "save":storage.fail=(String)a.get("fail");if(storage.fail==null)storage.fail="";d.save();break;case "requirement":requirement(d.getCommunication(),number(a,"slot"),rankValue(a.get("value")));break;case "clan":d.getCommunication().setClanName(string(a,"value"));break;case "uid":d.getInfo().translate(uid(a));break;case "session":d.setSession(new IoSession(string(a,"value")));break;case "clear_session":d.setSession(null);break;default:throw new UnsupportedOperationException();}return true;});steps.add(map("result",result,"account",accountValues(d.accountInfo),"state",communication(d.getCommunication()),"saveParsed",d.saveParsed,"ip",d.getIpAddress(),"uid",uidState(d.getInfo()),"updates",new ArrayList<>(storage.calls),"clockReads",oracle.Clock.reads,"delegates",Arrays.asList(d.getUsername(),d.getPassword(),d.getUid(),d.getCredits(),d.getLastLogin(),d.getTimePlayed(),d.getMuteTime(),d.getBanTime(),d.getMacAddress(),d.getCompName(),d.getSerial())));}return steps;}
 static Object metadata(Map<?,?> input){UserAccountInfo a=account((Map<?,?>)input.get("values"));a.setUsername("stored name");oracle.Clock.value=longNumber(input,"now");oracle.Clock.reads=0;MetadataSession session=new MetadataSession();MetadataInfo info=new MetadataInfo(string(input,"username"),1,2,1024,768,Arrays.asList(1,2,3,4),16);MetadataGate.prepare(session,info,a);ClientInfo c=session.getClientInfo();return map("response",session.getResponse(),"client",c==null?null:Arrays.asList(c.getDisplayMode(),c.getWindowMode(),c.getScreenWidth(),c.getScreenHeight()),"seed",session.getIsaacPair(),"username",session.getAssociatedUsername(),"opcode",session.getOpcode(),"details",session.getDetails()==null?null:communication(session.getDetails().getCommunication()),"shared",session.getDetails()!=null&&session.getDetails().accountInfo==a,"clockReads",oracle.Clock.reads);}
 static Object evaluate(Map<?,?> input){switch(string(input,"kind")){case "metadata":return metadata(input);case "requirements":return attempt(()->{List<Object> values=new ArrayList<>();for(ClanRank r:CommunicationInfo.parseClanRequirements(string(input,"text")))values.add(rank(r));return values;});case "contacts":return attempt(()->contacts(CommunicationInfo.parseContacts(string(input,"text"))));case "communication":return commActions(input);case "uid":return uidActions(input);case "details":return details(input);case "rights":return map("forId",attempt(()->Rights.forId(number(input,"ordinal")).ordinal()),"raw",attempt(()->Rights.values()[number(input,"ordinal")].ordinal()));case "ranks":List<Object> ranks=new ArrayList<>();for(ClanRank r:ClanRank.values())ranks.add(Arrays.asList(r.ordinal(),r.getValue(),r.getInfo(),r.toString()));return ranks;case "client":ClientInfo c=new ClientInfo(number(input,"display"),number(input,"window"),number(input,"width"),number(input,"height"));Object before=Arrays.asList(c.getDisplayMode(),c.getWindowMode(),c.getScreenWidth(),c.getScreenHeight(),c.isHighDetail(),c.isResizable());c.setDisplayMode(-c.getDisplayMode());c.setWindowMode(c.getWindowMode()+1);c.setScreenWidth(c.getScreenHeight());c.setScreenHeight(-1);return Arrays.asList(before,Arrays.asList(c.getDisplayMode(),c.getWindowMode(),c.getScreenWidth(),c.getScreenHeight(),c.isHighDetail(),c.isResizable()));default:throw new UnsupportedOperationException();}}
 public static void main(String[] args)throws Exception {UserAccountInfo.createDefault();BufferedReader reader=new BufferedReader(new InputStreamReader(java.lang.System.in,"UTF-8"));String line;while((line=reader.readLine())!=null){Map<String,Object> input=(Map<String,Object>)new JSONParser().parse(line);input.put("expected",evaluate(input));java.lang.System.out.println(JSONValue.toJSONString(input));}}
}
